using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_38f6b3520fb44fc2b4b344d29ed88a41.Client;

namespace sv_38f6b3520fb44fc2b4b344d29ed88a41.Auth;

/// <summary>
/// A server-side AuthenticationStateProvider that always returns a hardcoded
/// authenticated user and persists the auth state into PersistentComponentState
/// so the WebAssembly client can restore it after the runtime takes over.
/// </summary>
public sealed class ServerAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private static readonly AuthenticationState _authState;
    private readonly PersistingComponentStateSubscription _subscription;

    static ServerAuthenticationStateProvider()
    {
        var claims = new[]
        {
            new Claim(ClaimTypes.Name, "bob@example.com"),
            new Claim(ClaimTypes.Email, "bob@example.com"),
            new Claim(ClaimTypes.Role, "User"),
            new Claim(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, "HardcodedAuth");
        var user = new ClaimsPrincipal(identity);
        _authState = new AuthenticationState(user);
    }

    public ServerAuthenticationStateProvider(PersistentComponentState state)
    {
        _subscription = state.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => Task.FromResult(_authState);

    private Task OnPersistingAsync()
    {
        var principal = _authState.User;
        var email = principal.FindFirst(ClaimTypes.Email)?.Value ?? principal.Identity?.Name;
        var roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray();

        if (email is not null)
        {
            // This persists user info into the page so the WASM client can pick it up.
            // Without this, identity is lost when the WebAssembly runtime activates.
            var componentState = GetPersistentComponentState();
            componentState.PersistAsJson(nameof(UserInfo), new UserInfo
            {
                Email = email,
                Roles = roles,
            });
        }

        return Task.CompletedTask;
    }

    private PersistentComponentState GetPersistentComponentState()
    {
        // Access via the field captured during construction
        return _state;
    }

    private readonly PersistentComponentState _state;

    // Re-implement constructor to capture state field
    // (C# doesn't allow accessing constructor params in methods directly with this pattern,
    // so we use a field)
}

