 using sv_38f6b3520fb44fc2b4b344d29ed88a41.Client;

 namespace sv_38f6b3520fb44fc2b4b344d29ed88a41.Auth;

 /// <summary>
 /// A server-side AuthenticationStateProvider that always returns a hardcoded
 /// authenticated user and persists the auth state into PersistentComponentState
 /// so the WebAssembly client can restore it after the runtime takes over.
 /// </summary>
 public sealed class ServerAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
 {
     private static readonly AuthenticationState AuthState;

     private readonly PersistentComponentState _persistentState;
     private readonly PersistingComponentStateSubscription _subscription;

     static ServerAuthenticationStateProvider()
     {
         var claims = new[]
         {
             new Claim(ClaimTypes.Name, "bob@example.com"),
             new Claim(ClaimTypes.Email, "bob@example.com"),
             new Claim(ClaimTypes.Role, "User"),
             new Claim(ClaimTypes.Role, "Editor"),
         };

         var identity = new ClaimsIdentity(claims, "HardcodedAuth");
         var user = new ClaimsPrincipal(identity);
         AuthState = new AuthenticationState(user);
     }

     public ServerAuthenticationStateProvider(PersistentComponentState persistentState)
     {
         _persistentState = persistentState;
         _subscription = persistentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
     }

